const LABEL={done:'Implemented',partial:'Partial',planned:'Planned'};

export function prdSection(){
 let md='## Claude Code and Codex feature parity\n\nEvery capability Claude Code and Codex offer that fits code by aqeel, plus features requested directly. Implemented means verified in the running app. Order of work: P0 first, then P1, then P2.\n\n';
 for(const [prefix,name] of AREAS){
  const rows=FEATURES.filter(f=>f[0].split('-')[0]===prefix||(prefix==='MODEL'&&f[0].startsWith('AUTH')));if(!rows.length)continue;
  md+='### '+name+'\n\n| ID | Capability | Current status | Acceptance criterion | Source | Priority |\n|---|---|---|---|---|---|\n';
  for(const [id,title,source,priority,status,acceptance] of rows)md+=`| ${id} | ${title} | ${LABEL[status]} | ${acceptance} | ${source} | ${priority} |\n`;
  md+='\n';
 }
 return md;
}

// Existing board cards whose scope changed with this inventory.
const UPDATES={
 'BUILD-02':{status:'done',implementation:'Implemented',notes:'Superseded by AGENT-01/02/08: native Codex app-server and Claude stream-json runs with live events and resumed sessions, verified live.'},
 'MODEL-02':null,'AUTH-02':null, // replaced by inventory rows with the same id
 'CHAT-02':{status:'done',implementation:'Implemented',notes:'Split into PROJ-04 to PROJ-09 and PROJ-12, all implemented.'},
 'FILE-02':{status:'done',implementation:'Implemented',notes:'Files view tree with folders, keyboard navigation (arrows, Enter, F2, Delete), rename/move and delete recorded as versions in Changes; per-block revert and line comments in Changes (AUD1-07, AUD1-08).'},
 'SHELL-02':{priority:'P0',notes:'Full PTY terminal. Related: SHELL-03 (done), SHELL-04 (done), SHELL-05 tabs.'},
 'PROJECT-02':{priority:'P0',notes:'Open an existing local folder in place. GitHub import is GIT-02.'},
 'GIT-01':{status:'done',implementation:'Implemented',notes:'Split into GIT-02 to GIT-08; all implemented except GIT-05 (partial: PR reviews and comments stay on GitHub).'},
 'MEDIA-01':{priority:'P0',notes:'Paste or drop screenshots and images into the composer for both providers.'},
 'PREVIEW-02':{notes:'Delivered through SHELL-07 dev server manager.'},
};

async function main(){
 const root=path.join(path.dirname(fileURLToPath(import.meta.url)),'..');
 const prdPath=path.join(root,'PRODUCT-REQUIREMENTS.md'),boardPath=path.join(root,'data','development.json');
 let prd=await readFile(prdPath,'utf8');const marker='## Claude Code and Codex feature parity';
 const start=prd.indexOf(marker);if(start>=0){const next=prd.indexOf('\n## ',start+marker.length);prd=prd.slice(0,start)+(next>=0?prd.slice(next+1):'')}
 const at=prd.indexOf('## Architecture and local data');prd=at>=0?prd.slice(0,at)+prdSection()+prd.slice(at):prd+'\n'+prdSection();
 await writeFile(prdPath,prd);

 const board=JSON.parse(await readFile(boardPath,'utf8'));const now=new Date().toISOString();let added=0,updated=0;
 for(const [id,patch] of Object.entries(UPDATES)){const t=board.tasks.find(t=>t.id===id);if(!t||!patch||Object.entries(patch).every(([k,v])=>t[k]===v))continue;const from=t.status;Object.assign(t,patch);t.updatedAt=now;t.history.push({at:now,from,to:t.status,note:'Parity inventory: '+(patch.notes||'scope updated')});updated++}
 for(const [id,title,source,priority,status,acceptance] of FEATURES){
  const s=status==='done'?'done':status==='partial'&&id==='GIT-02'?'in_progress':'backlog';
  const card={id,title,implementation:LABEL[status],status:s,priority,acceptance,notes:'Parity source: '+source+'.'+(status==='done'?' Verified in this build.':status==='partial'?' Partly working; see acceptance criterion.':''),updatedAt:now};
  const existing=board.tasks.find(t=>t.id===id);
  if(existing){const from=existing.status;if(existing.status==='done'&&card.status!=='done')continue;if(['title','status','priority','acceptance','implementation'].every(k=>existing[k]===card[k]))continue;Object.assign(existing,card);existing.history.push({at:now,from,to:card.status,note:'Updated from the parity inventory.'});updated++}
  else{board.tasks.push({...card,history:[{at:now,from:'backlog',to:card.status,note:'Added from the Claude Code and Codex parity inventory.'}]});added++}
 }
 board.revision++;await writeFile(boardPath+'.tmp',JSON.stringify(board,null,2));await rename(boardPath+'.tmp',boardPath);
 const count=s=>board.tasks.filter(t=>t.status===s).length;
 console.log(`PRD updated · board: ${added} added, ${updated} updated · ${board.tasks.length} cards (done ${count('done')}, in progress ${count('in_progress')}, backlog ${count('backlog')})`);
}
if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url))await main();
